/**
 * issue #89: pure, framework-agnostic validation/normalization of the
 * generic Workflow-level suspension descriptor ABI.
 *
 * A suspending Activity result carries `{ sends: [], suspension: {...} }`
 * instead of ordinary resolved `sends`. This module knows the shape of that
 * `suspension` object ONLY - it has zero knowledge of Node-RED node types
 * (no `if (node.type === "delay")` anywhere, per the issue's hard
 * requirement) and zero dependency on `@temporalio/*` (so both
 * `activities.js`, which must stay Temporal-free, and `workflows.js`, which
 * must stay node-type-agnostic, can both safely `require` it).
 *
 * Two suspension types are defined:
 *
 *   { type: "timer", durationMs: <positive finite number>, continuation }
 *   { type: "signal", key: <non-empty string>, continuation }
 *
 * `continuation` is opaque adapter-owned data - this module never inspects
 * it beyond passing it through unchanged (it must already be plain/
 * serializable by the time it reaches here; that's a normal Temporal
 * payload-converter concern, not re-implemented here - see the issue's
 * "no second serializer" requirement).
 */

"use strict";

/**
 * @param {string} message
 * @returns {Error} with `.code = "SUSPENSION_INVALID"`, for callers that
 *   want to map validation failures onto a nonRetryable Activity/Workflow
 *   error uniformly.
 */
function invalid(message) {
    var err = new Error(message);
    err.code = "SUSPENSION_INVALID";
    return err;
}

/**
 * Validates and normalizes a suspension descriptor. Throws (never returns
 * falsy) on any malformed input - callers must not silently fall back to
 * local waiting on a bad descriptor (see issue #89's validation
 * requirements).
 *
 * @param {*} suspension - candidate descriptor, as returned by an Activity-
 *   side suspension adapter's `plan(node, msg)`.
 * @returns {{type:"timer", durationMs:number, continuation:*}|{type:"signal", key:string, continuation:*}}
 */
function validateSuspension(suspension) {
    if (!suspension || typeof suspension !== "object" || Array.isArray(suspension)) {
        throw invalid("suspension descriptor must be a plain object");
    }

    if (suspension.type === "timer") {
        var durationMs = suspension.durationMs;
        if (typeof durationMs !== "number" || !Number.isFinite(durationMs) || durationMs <= 0) {
            throw invalid("timer suspension requires a positive finite durationMs");
        }
        return { type: "timer", durationMs: durationMs, continuation: suspension.continuation };
    }

    if (suspension.type === "signal") {
        var key = suspension.key;
        if (typeof key !== "string" || key.length === 0) {
            throw invalid("signal suspension requires a non-empty string key");
        }
        return { type: "signal", key: key, continuation: suspension.continuation };
    }

    throw invalid("unknown suspension type: " + JSON.stringify(suspension.type));
}

module.exports = { validateSuspension };
